group\"><!-- wp:group {\"metadata\":{\"name\":\"Timeline Header\"},\"style\":{\"layout\":{\"selfStretch\":\"fit\",\"flexSize\":null}},\"className\":\"nfd-gap-md nfd-text-sm nfd-text-primary\",\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\",\"verticalAlignment\":\"center\"}} --><div class=\"nfd-gap-md nfd-text-sm nfd-text-primary wp-block-group\"><!-- wp:group {\"metadata\":{\"name\":\"Time\"},\"className\":\"nfd-shrink-0 nfd-rounded-full\",\"layout\":{\"type\":\"constrained\"},\"nfdGroupTheme\":\"primary\"} --><div class=\"nfd-shrink-0 nfd-rounded-full wp-block-group nfd-bg-surface nfd-theme-primary\"><!-- wp:paragraph {\"metadata\":{\"name\":\"Time\"},\"style\":{\"typography\":{\"fontStyle\":\"normal\",\"fontWeight\":\"400\"},\"spacing\":{\"padding\":{\"top\":\"4px\",\"bottom\":\"4px\",\"left\":\"12px\",\"right\":\"12px\"}}},\"className\":\"nfd-shrink-0 nfd-text-contrast\"} --><p class=\"nfd-shrink-0 nfd-text-contrast\" style=\"padding-top:4px;padding-right:12px;padding-bottom:4px;padding-left:12px;font-style:normal;font-weight:400\">May 2003</p><!-- /wp:paragraph --></div><!-- /wp:group --><!-- wp:separator {\"className\":\"is-style-wide nfd-text-subtle nfd-border-b\"} --><hr class=\"is-style-wide nfd-text-subtle nfd-border-b wp-block-separator has-alpha-channel-opacity\"/><!-- /wp:separator --></div><!-- /wp:group --><!-- wp:group {\"metadata\":{\"name\":\"Timeline Content\"},\"style\":{\"spacing\":{\"padding\":{\"right\":\"var:preset|spacing|20\"}}},\"className\":\"nfd-gap-sm\",\"layout\":{\"type\":\"flex\",\"orientation\":\"vertical\",\"justifyContent\":\"stretch\"}} --><div class=\"nfd-gap-sm wp-block-group\" style=\"padding-right:var(--wp--preset--spacing--20)\"><!-- wp:heading {\"level\":3,\"metadata\":{\"name\":\"Heading\"},\"className\":\"nfd-text-md nfd-text-contrast\"} --><h3 class=\"nfd-text-md nfd-text-contrast wp-block-heading\">WordPress Launch</h3><!-- /wp:heading --><!-- wp:paragraph {\"metadata\":{\"name\":\"Description\"},\"className\":\"nf